:root {
  --ink: #17233c;
  --paper: #fffefd;
  --line: #d7dce7;
  --blue: #4568d4;
  --blue-pale: #e9edff;
  --mint: #d8f3e7;
  --green: #197653;
  --muted: #6a7487;
}

* {
  box-sizing: border-box;
}

.service-card {
  width: 480px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header,
.title-group,
.footer,
.status,
.detail-row {
  display: flex;
  align-items: center;
}

.card-header,
.footer {
  justify-content: space-between;
}

.title-group {
  gap: 10px;
}

.unit-mark {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 11px;
  background: var(--blue);
  color: var(--paper);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: .04em;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .08em;
}

h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1;
  letter-spacing: -.03em;
}

.status {
  gap: 6px;
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--mint);
  color: var(--green);
  font-size: 12px;
  font-weight: 700;
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
}

.main-grid {
  display: grid;
  grid-template-columns: 132px 1fr;
  gap: 18px;
  margin: 17px 0;
  padding: 15px;
  border-radius: 13px;
  background: var(--blue-pale);
}

.battery-visual {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin: 0;
}

.battery-top {
  width: 26px;
  height: 5px;
  border-radius: 3px 3px 0 0;
  background: var(--ink);
}

.battery-body {
  display: flex;
  align-items: end;
  width: 72px;
  height: 54px;
  padding: 5px;
  border: 3px solid var(--ink);
  border-radius: 8px;
}

.charge {
  width: 100%;
  height: 92%;
  border-radius: 2px;
  background: var(--blue);
}

.battery-label {
  margin-top: 7px;
  color: var(--ink);
  font-size: 12px;
  font-weight: 800;
}

.details {
  display: grid;
  align-content: center;
  gap: 7px;
}

.detail-row {
  justify-content: space-between;
  margin: 0;
  padding-bottom: 7px;
  border-bottom: 1px solid var(--line);
  font-size: 12px;
}

.detail-row:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}

.detail-row span {
  color: var(--muted);
}

.detail-row strong {
  font-weight: 750;
}

.footer {
  color: var(--muted);
  font-size: 12px;
}

button {
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--paper);
  color: var(--blue);
  font-size: 12px;
  font-weight: 800;
}
